const cds = require('../cds');
const crypto = require('node:crypto');
const http = require('node:http');

const DEBUG = cds.debug('cli');

// Fixed candidate ports for the loopback redirect: IAS matches redirect_uri exactly
// (incl. port), so `http://localhost:<port>/callback` must be pre-registered. First free wins.
const DEFAULT_PORTS = [8990, 8991, 8992, 8993, 8994];

// Base64-URL without padding (PKCE, RFC 7636).
function base64url(buffer) {
    return buffer.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

// PKCE code_verifier + S256 code_challenge.
function createPkce() {
    const codeVerifier = base64url(crypto.randomBytes(32));
    const codeChallenge = base64url(crypto.createHash('sha256').update(codeVerifier).digest());
    return { codeVerifier, codeChallenge };
}

// Opens the URL in the default browser; returns whether a command was spawned.
function openBrowser(url) {
    const platform = process.platform;
    let command, args, spawnOpts = { stdio: 'ignore', detached: true };
    if (platform === 'darwin') {
        command = 'open';
        args = [url];
    } else if (platform === 'win32') {
        // Caret-escape cmd metacharacters (esp. `&`) so `start` doesn't truncate the URL.
        const escaped = url.replace(/[&^|<>()%"]/g, m => '^' + m);
        command = `start "" ${escaped}`;
        args = [];
        spawnOpts = { ...spawnOpts, shell: true, windowsVerbatimArguments: true };
    } else {
        command = 'xdg-open';
        args = [url];
    }
    try {
        const child = require('node:child_process').spawn(command, args, spawnOpts);
        child.on('error', err => DEBUG?.(`Failed to open browser via ${command}: ${err.message}`));
        child.unref();
        return true;
    } catch (err) {
        DEBUG?.(`Failed to open browser via ${command}: ${err.message}`);
        return false;
    }
}

function escapeHtml(s) {
    return String(s)
        .replaceAll('&', '&amp;')
        .replaceAll('<', '&lt;')
        .replaceAll('>', '&gt;')
        .replaceAll('"', '&quot;');
}

function htmlResponse(title, message) {
    return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title></head>` +
        `<body style="font-family:sans-serif;text-align:center;padding-top:3em">` +
        `<h1>${escapeHtml(title)}</h1><p>${escapeHtml(message)}</p></body></html>`;
}

/**
 * OAuth 2.0 Authorization Code + PKCE via a loopback redirect (RFC 8252): starts a
 * local server on a fixed port (IAS requires an exact, pre-registered redirect_uri),
 * opens the browser, and resolves with the authorization code.
 *
 * @param {object} metadata Authorization metadata from the server.
 * @param {string} metadata.authorization_endpoint
 * @param {string} metadata.client_id
 * @param {string} [metadata.scope]
 * @param {object} [options]
 * @param {boolean} [options.noBrowser] Only print the URL instead of opening a browser.
 * @param {number} [options.timeout] Milliseconds to wait for the redirect (default 300000).
 * @param {number[]} [options.ports] Candidate fixed ports for the loopback server.
 * @param {string} [options.host] Loopback host to bind/redirect to (default 'localhost').
 * @returns {Promise<{code: string, codeVerifier: string, redirectUri: string}>}
 */
async function authorizeViaBrowser(metadata, { noBrowser = false, timeout = 5 * 60 * 1000, ports = DEFAULT_PORTS, host = 'localhost' } = {}) {
    const { authorization_endpoint, client_id, scope, app_tid } = metadata;
    if (!authorization_endpoint || !client_id) {
        throw 'Incomplete authorization metadata received from server (missing authorization_endpoint or client_id).';
    }

    const { codeVerifier, codeChallenge } = createPkce();
    const state = base64url(crypto.randomBytes(16));

    return new Promise((resolve, reject) => {
        let settled = false;
        let timer;
        const finish = (fn, arg) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            server.close();
            fn(arg);
        };

        const server = http.createServer((req, res) => {
            const requestUrl = new URL(req.url, redirectBase);
            if (requestUrl.pathname !== '/callback') {
                res.statusCode = 404;
                return res.end();
            }
            const params = requestUrl.searchParams;
            const error = params.get('error');
            const returnedState = params.get('state');
            const code = params.get('code');

            if (error) {
                res.setHeader('Content-Type', 'text/html');
                res.end(htmlResponse('Login failed', `The identity provider returned an error: ${error}.`));
                return finish(reject, `Authorization failed: ${error}${params.get('error_description') ? ` (${params.get('error_description')})` : ''}.`);
            }
            if (returnedState !== state) {
                res.statusCode = 400;
                res.setHeader('Content-Type', 'text/html');
                res.end(htmlResponse('Login failed', 'State mismatch. Please try again.'));
                return finish(reject, 'Authorization failed: state mismatch (possible CSRF). Please retry the login.');
            }
            if (!code) {
                res.statusCode = 400;
                res.setHeader('Content-Type', 'text/html');
                res.end(htmlResponse('Login failed', 'No authorization code received.'));
                return finish(reject, 'Authorization failed: no authorization code received.');
            }

            res.setHeader('Content-Type', 'text/html');
            res.end(htmlResponse('Login successful', 'You may now close this tab and return to the terminal.'));
            finish(resolve, { code, codeVerifier, redirectUri });
        });

        server.on('error', err => {
            if (err.code === 'EADDRINUSE' && candidates.length) return listenNext(); // try next port
            finish(reject, `Failed to start local login server: ${err.message}`);
        });

        let redirectBase, redirectUri;
        const candidates = [...ports];
        const listenNext = () => {
            const port = candidates.shift();
            server.listen(port, '127.0.0.1');
        };
        server.on('listening', () => {
            const { port } = server.address();
            redirectBase = `http://${host}:${port}`;
            redirectUri = `${redirectBase}/callback`;

            const authUrl = new URL(authorization_endpoint);
            authUrl.searchParams.set('response_type', 'code');
            authUrl.searchParams.set('client_id', client_id);
            authUrl.searchParams.set('redirect_uri', redirectUri);
            authUrl.searchParams.set('code_challenge', codeChallenge);
            authUrl.searchParams.set('code_challenge_method', 'S256');
            authUrl.searchParams.set('state', state);
            if (scope) authUrl.searchParams.set('scope', scope);
            if (app_tid) authUrl.searchParams.set('app_tid', app_tid); // multi-tenant IAS client disambiguation

            timer = setTimeout(
                () => finish(reject, 'Timed out waiting for browser login. Please try again.'),
                timeout
            );
            timer.unref?.();

            const url = authUrl.toString();
            if (noBrowser || !openBrowser(url)) {
                console.log('Please open the following URL in your browser to log in:');
                console.log(`\n  ${url}\n`);
            } else {
                console.log('Opening browser for single sign-on. Complete the login there to continue…');
                DEBUG?.(`Authorization URL: ${url}`);
            }
            DEBUG?.(`Waiting for the authorization code on ${redirectUri}`);
        });
        listenNext();
    });
}

module.exports = { authorizeViaBrowser, createPkce, openBrowser, DEFAULT_PORTS };
